select tid.id, tid.main_id, tid.sku_id, tid.sku_no, tid.qty, tid.unit, tid.in_warehouse_location, tid.out_warehouse_location, tid.remark, tid.source_detail_id from transfer_info ti inner join transfer_info_detail tid on ti.id = tid.main_id and tid.is_deleted = false
ti.is_deleted = false and ti.invalid_status = false and tid.source_detail_id in
#{item}

select tid.id as id, tid.main_id as mainId, tid.sku_id, tid.sku_no, tid.qty, tid.out_warehouse_id, tid.in_warehouse_id, tid.in_warehouse_location, tid.out_warehouse_location, tid.remark, tid.source_detail_id, inWarehouse.name as inWarehouseName, inWarehouse.charge_id as inWarehouseChargeId, outWarehouse.name as outWarehouseName, outWarehouse.charge_id as outWarehouseChargeId from transfer_info_detail AS tid left join warehouse AS inWarehouse on tid.in_warehouse_id = inWarehouse.id left join warehouse AS outWarehouse on outWarehouse.id = tid.out_warehouse_id where tid.is_deleted = false and inWarehouse.is_deleted = false and outWarehouse.is_deleted = false and tid.main_id in
#{item}
order by tid.id asc
